form label {
  display: block;
}

table {
  width: 100%;
}

img {
  display: block;
  margin-inline: auto;
}

nav {
  display: flex;
}

header {
  display: flex;
  flex-direction: column;
}

main {
  display: flex;
  flex-direction: column;
}

nav {
  justify-content: center;
}

header {
  align-items: center;
}

nav {
  gap: 1rem;
}

nav {
  flex-wrap: wrap;
}

form {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

main {
  flex-direction: row;
  flex-wrap: wrap;
  gap: 1.5rem;
}

footer {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 1rem;
}

main > section,
main > article {
  flex: 1 1 18rem;
}

nav {
  align-items: center;
}

nav a {
  flex: 0 0 auto;
}

main {
  display: grid;
}

main {
  grid-template-columns: 1fr 1fr;
}

main {
  grid-template-rows: auto;
}

main {
  gap: 1rem;
}

main {
  grid-template-columns: repeat(2, 1fr);
}

main > :first-child {
  grid-column: 1 / -1;
}

main {
  width: 100%;
}

main {
  grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr));
}

main {
  max-width: 72rem;
  margin-inline: auto;
}

main {
  grid-template-columns: 1fr;
}

@media (min-width: 48rem) {
  main {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

main > * {
  min-width: 0;
}

@media (min-width: 64rem) {
  main {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

